create extension if not exists pgcrypto;
create table if not exists location_review_ml_features (location_id uuid primary key, approved_review_count integer default 0, verified_review_count integer default 0, recent_review_count integer default 0, avg_rating numeric default 0, avg_ai_score_boost numeric default 0, positive_review_count integer default 0, neutral_review_count integer default 0, negative_review_count integer default 0, quiet_score numeric default 0, loud_score numeric default 0, romantic_score numeric default 0, group_score numeric default 0, family_score numeric default 0, upscale_score numeric default 0, casual_score numeric default 0, photo_worthy_score numeric default 0, lively_score numeric default 0, relaxed_score numeric default 0, grown_vibe_score numeric default 0, date_night_score numeric default 0, birthday_score numeric default 0, girls_night_score numeric default 0, service_score numeric default 0, food_score numeric default 0, ambiance_score numeric default 0, value_score numeric default 0, overall_review_quality_score numeric default 0, review_confidence_score numeric default 0, review_freshness_score numeric default 0, wait_penalty numeric default 0, overpriced_penalty numeric default 0, service_penalty numeric default 0, noise_penalty numeric default 0, crowded_penalty numeric default 0, quiet_mention_count integer default 0, loud_mention_count integer default 0, romantic_mention_count integer default 0, group_mention_count integer default 0, family_mention_count integer default 0, photo_worthy_mention_count integer default 0, service_issue_count integer default 0, wait_issue_count integer default 0, value_issue_count integer default 0, top_positive_terms text[] default '{}', top_negative_terms text[] default '{}', best_for_terms text[] default '{}', avoid_if_terms text[] default '{}', review_summary text null, last_review_at timestamptz null, calculated_at timestamptz default now(), created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists search_result_ml_features (id uuid primary key default gen_random_uuid(), result_key text not null, query_fingerprint text, intent_bucket text, location_id uuid null, restaurant_id uuid null, activity_id uuid null, pair_key text null, market text null, shown_count integer default 0, click_count integer default 0, save_count integer default 0, complete_count integer default 0, reservation_click_count integer default 0, call_click_count integer default 0, website_click_count integer default 0, negative_feedback_count integer default 0, bounce_count integer default 0, immediate_research_count integer default 0, result_quality_score numeric default 0, confidence_score numeric default 0, last_seen_at timestamptz null, calculated_at timestamptz default now(), created_at timestamptz default now(), updated_at timestamptz default now());
create index if not exists search_result_ml_features_result_key_idx on search_result_ml_features(result_key); create index if not exists search_result_ml_features_query_idx on search_result_ml_features(query_fingerprint); create index if not exists search_result_ml_features_intent_idx on search_result_ml_features(intent_bucket); create index if not exists search_result_ml_features_location_idx on search_result_ml_features(location_id); create index if not exists search_result_ml_features_pair_idx on search_result_ml_features(pair_key); create index if not exists search_result_ml_features_score_idx on search_result_ml_features(result_quality_score);
create table if not exists location_pair_ml_features (id uuid primary key default gen_random_uuid());
alter table location_pair_ml_features add column if not exists pair_key text; alter table location_pair_ml_features add column if not exists restaurant_location_id uuid; alter table location_pair_ml_features add column if not exists activity_location_id uuid; alter table location_pair_ml_features add column if not exists market text; alter table location_pair_ml_features add column if not exists distance_miles numeric; alter table location_pair_ml_features add column if not exists walk_minutes numeric; alter table location_pair_ml_features add column if not exists drive_minutes numeric; alter table location_pair_ml_features add column if not exists same_neighborhood boolean default false; alter table location_pair_ml_features add column if not exists same_city boolean default false; alter table location_pair_ml_features add column if not exists shown_count integer default 0; alter table location_pair_ml_features add column if not exists click_count integer default 0; alter table location_pair_ml_features add column if not exists save_count integer default 0; alter table location_pair_ml_features add column if not exists complete_count integer default 0; alter table location_pair_ml_features add column if not exists reservation_click_count integer default 0; alter table location_pair_ml_features add column if not exists negative_feedback_count integer default 0; alter table location_pair_ml_features add column if not exists pair_compatibility_score numeric default 0; alter table location_pair_ml_features add column if not exists review_compatibility_score numeric default 0; alter table location_pair_ml_features add column if not exists time_fit_score numeric default 0; alter table location_pair_ml_features add column if not exists market_fit_score numeric default 0; alter table location_pair_ml_features add column if not exists distance_fit_score numeric default 0; alter table location_pair_ml_features add column if not exists confidence_score numeric default 0; alter table location_pair_ml_features add column if not exists best_for_terms text[] default '{}'; alter table location_pair_ml_features add column if not exists watchout_terms text[] default '{}'; alter table location_pair_ml_features add column if not exists calculated_at timestamptz default now(); alter table location_pair_ml_features add column if not exists updated_at timestamptz default now(); create index if not exists location_pair_ml_features_pair_key_idx on location_pair_ml_features(pair_key);
create table if not exists search_negative_feedback (id uuid primary key default gen_random_uuid(), user_id uuid null, session_id text null, search_event_id uuid null, raw_query text null, normalized_query text null, intent_bucket text null, location_id uuid null, restaurant_location_id uuid null, activity_location_id uuid null, pair_key text null, feedback_type text not null, feedback_label text null, feedback_note text null, market text null, created_at timestamptz default now(), constraint search_negative_feedback_type_check check (feedback_type in ('not_a_fit','too_far','wrong_vibe','too_expensive','too_loud','too_quiet','wrong_category','bad_pair','closed_or_unavailable','duplicate','bad_photo','other')));
create table if not exists market_ml_features (market_key text primary key, market_name text, search_count integer default 0, pair_search_count integer default 0, avg_accepted_pair_distance_miles numeric default 0, avg_saved_pair_distance_miles numeric default 0, avg_completed_pair_distance_miles numeric default 0, walking_preference_score numeric default 0, driving_preference_score numeric default 0, same_neighborhood_preference_score numeric default 0, same_city_preference_score numeric default 0, restaurant_only_success_score numeric default 0, pair_success_score numeric default 0, top_activity_types text[] default '{}', top_cuisines text[] default '{}', top_vibes text[] default '{}', confidence_score numeric default 0, calculated_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists time_of_day_ml_features (id uuid primary key default gen_random_uuid(), time_bucket text not null, day_bucket text not null, intent_bucket text null, market_key text null, search_count integer default 0, save_count integer default 0, complete_count integer default 0, top_activity_types text[] default '{}', top_cuisines text[] default '{}', top_vibes text[] default '{}', time_fit_score numeric default 0, confidence_score numeric default 0, calculated_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists user_preference_ml_features (user_id uuid primary key, preferred_markets text[] default '{}', preferred_neighborhoods text[] default '{}', preferred_cuisines text[] default '{}', preferred_activity_types text[] default '{}', preferred_vibes text[] default '{}', preferred_occasions text[] default '{}', avoided_activity_types text[] default '{}', avoided_cuisines text[] default '{}', walking_preference_score numeric default 0, driving_preference_score numeric default 0, quiet_preference_score numeric default 0, lively_preference_score numeric default 0, budget_preference_score numeric default 0, upscale_preference_score numeric default 0, personalization_confidence_score numeric default 0, last_activity_at timestamptz null, calculated_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists booking_likelihood_ml_features (location_id uuid primary key, reservation_enabled boolean default false, owner_active boolean default false, booking_request_count integer default 0, confirmed_booking_count integer default 0, completed_booking_count integer default 0, cancelled_booking_count integer default 0, no_show_count integer default 0, avg_response_minutes numeric default null, confirmation_rate numeric default 0, completion_rate numeric default 0, cancellation_rate numeric default 0, no_show_rate numeric default 0, booking_likelihood_score numeric default 0, booking_confidence_score numeric default 0, last_booking_at timestamptz null, calculated_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists business_quality_ml_features (location_id uuid primary key, profile_completeness_score numeric default 0, address_quality_score numeric default 0, photo_readiness_score numeric default 0, hours_quality_score numeric default 0, contact_quality_score numeric default 0, website_quality_score numeric default 0, owner_claimed_score numeric default 0, reservation_readiness_score numeric default 0, duplicate_risk_score numeric default 0, public_search_ready_score numeric default 0, business_trust_score numeric default 0, missing_fields text[] default '{}', recommended_actions text[] default '{}', calculated_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists duplicate_ml_candidates (id uuid primary key default gen_random_uuid(), location_id_a uuid not null, location_id_b uuid not null, name_similarity numeric default 0, address_similarity numeric default 0, phone_similarity numeric default 0, website_similarity numeric default 0, geo_similarity numeric default 0, category_similarity numeric default 0, photo_similarity numeric default 0, duplicate_confidence_score numeric default 0, status text default 'pending', reviewed_by uuid null, reviewed_at timestamptz null, review_note text null, created_at timestamptz default now(), updated_at timestamptz default now()); create unique index if not exists duplicate_ml_candidates_unordered_idx on duplicate_ml_candidates(least(location_id_a, location_id_b), greatest(location_id_a, location_id_b));
create table if not exists photo_quality_ml_features (location_id uuid primary key, photo_count integer default 0, has_primary_photo boolean default false, primary_photo_url text null, photo_quality_score numeric default 0, primary_photo_score numeric default 0, duplicate_photo_risk_score numeric default 0, logo_only_risk_score numeric default 0, blur_risk_score numeric default 0, bad_aspect_ratio_risk_score numeric default 0, category_fit_score numeric default 0, card_crop_fit_score numeric default 0, needs_photo_repair boolean default false, recommended_photo_actions text[] default '{}', calculated_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists owner_lead_ml_features (location_id uuid primary key, claim_status text null, owner_user_id uuid null, plan_name text null, search_impressions_30d integer default 0, views_30d integer default 0, saves_30d integer default 0, reservation_clicks_30d integer default 0, call_clicks_30d integer default 0, website_clicks_30d integer default 0, review_count integer default 0, business_trust_score numeric default 0, reservation_readiness_score numeric default 0, owner_lead_score numeric default 0, lead_priority text default 'normal', recommended_pitch text null, recommended_actions text[] default '{}', assigned_to uuid null, last_contact_at timestamptz null, calculated_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists advanced_ml_score_runs (id uuid primary key default gen_random_uuid(), run_type text not null, started_at timestamptz default now(), completed_at timestamptz null, status text default 'running', records_scanned integer default 0, records_updated integer default 0, errors text[] default '{}', metadata jsonb default '{}'::jsonb);
do $$ declare t text; begin foreach t in array array['location_review_ml_features','search_result_ml_features','location_pair_ml_features','search_negative_feedback','market_ml_features','time_of_day_ml_features','user_preference_ml_features','booking_likelihood_ml_features','business_quality_ml_features','duplicate_ml_candidates','photo_quality_ml_features','owner_lead_ml_features','advanced_ml_score_runs'] loop execute format('alter table %I enable row level security', t); end loop; end $$;
